@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : string
}

class ScientificArticle {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
}

class TechnicalReport extends ScientificArticle {}

class AuthorPosition {
  + position : int
}

class Reviewer {
  + reviewDetails : string
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "1" -- "*" ScientificArticle : author
Person "0..*" -- "0..*" ScientificArticle : reviewer
Person "*" -- "1" ResearchInstitution : works for
ResearchInstitution "1" -- "*" TechnicalReport : publishes
Publisher "1" -- "*" Journal : publishes
ResearchInstitution "*" -- "*" Journal : subscribes
Journal "1" -- "*" PeerReviewedPaper : publishes
PeerReviewedPaper "*" -- "1" Reviewer : reviewed by
ScientificArticle "1" -- "*" AuthorPosition : has
AuthorPosition "*" -- "1" Person : refers to

@enduml

